import { Image, Text } from "react-native";

import { Hit } from "@/components/ui";

const GOOGLE_MARK =
  "data:image/svg+xml;base64,";

/** Light Google sign-in button. The label is centered, matching the Apple button. */
export function StandardGoogleButton({ disabled, onPress }: { disabled: boolean; onPress: () => void }) {
  return (
    <Hit
      label="Sign in with Google"
      disabled={disabled}
      onPress={onPress}
      style={{
        alignSelf: "stretch",
        height: 48,
        borderRadius: 4,
        backgroundColor: "#FFFFFF",
        borderWidth: 1,
        borderColor: "#747775",
        alignItems: "center",
        justifyContent: "center",
        flexDirection: "row",
        gap: 10,
      }}
    >
      <Image source={{ uri: GOOGLE_MARK }} style={{ width: 18, height: 18 }} />
      <Text style={{ color: "#1F1F1F", fontSize: 16, fontWeight: "500" }}>Sign in with Google</Text>
    </Hit>
  );
}
